  if(action==='new-food'){user();openFood();return;}
  if(action==='edit-food'){openFood(foods().find(f=>f.id===element.dataset.id));return;}
  if(action==='new-recipe'){user();openRecipe();return;}
  if(action==='new-weight'){user();openWeight();return;}
  if(action==='new-activity'){user();openActivity();return;}
