  if(action==='favorite')return perform(async()=>{const f=foods().find(r=>r.id===element.dataset.id);await write('nutrition_foods',{favorite:!f.favorite},f.id);return true;},'Favorite updated.');
  if(action==='add-ingredient'){
   const f=foods().find(f=>f.id===val('ingredientFood')),quantity=nval('ingredientQuantity');if(!f||!quantity||quantity<=0)throw Error('Choose a food and positive quantity.');recipeDraft.push({food_id:f.id,ingredient_name:f.name,quantity,unit:f.basis_unit});renderDraft();return;
