    download('financeflow-import-report.json',JSON.stringify(importReport,null,2));return importReport.created.length>0;
   },'Import finished. Created, skipped and flagged records are listed in Settings.');
  }
  if(action==='export-import-report'){if(importReport)download('financeflow-import-report.json',JSON.stringify(importReport,null,2));return;}
  if(action==='export-json'||action==='export-csv')return perform(async owner=>{
